/*!
 * ScrollTrigger Compatibility Library (NEXUS VR Engine)
 */
(function(window) {
  "use strict";

  const ScrollTrigger = {
    version: "3.12.5",
    register: function() { return true; },
    create: function(config) {
      if (!config) return {};
      
      const trigger = typeof config.trigger === "string" ? document.querySelector(config.trigger) : config.trigger;
      if (!trigger) return {};

      let lastProgress = 0;
      function checkScroll() {
        const rect = trigger.getBoundingClientRect();
        const winHeight = window.innerHeight;
        const totalDist = rect.height + winHeight;
        const currentDist = winHeight - rect.top;
        let progress = Math.min(Math.max(currentDist / totalDist, 0), 1);

        if (progress !== lastProgress) {
          lastProgress = progress;
          if (typeof config.onUpdate === "function") {
            config.onUpdate({ progress: progress });
          }
        }
      }

      window.addEventListener("scroll", checkScroll, { passive: true });
      checkScroll();

      return {
        kill: function() {
          window.removeEventListener("scroll", checkScroll);
        }
      };
    }
  };

  if (window.gsap) {
    window.gsap.registerPlugin = function() { return true; };
    window.gsap.ScrollTrigger = ScrollTrigger;
  }

  window.ScrollTrigger = ScrollTrigger;
})(window);
